import datetime as dt,os,tempfile,unittest
from app import impact_v36 as impact
from app import position_plans_v361 as plans
from app import lifecycle_executor_v363 as ex
class Executor(unittest.TestCase):
 def db(self):
  t=tempfile.TemporaryDirectory();d=impact.connect(os.path.join(t.name,'x.db'));d.executescript("""create table decisions(id integer primary key,created text,news_uid text,ticker text,action text,score real,reason text,rules_version text,status text,entry_price real,shares real,amount real,theme text);create table news(id integer primary key,uid text unique,source text,title text,summary text,url text,published text,ingested text,trust real);create table theses(decision_id integer,event_type text,thesis_json text,model_version text);create table positions(id integer primary key,ticker text,theme text,opened text,entry_price real,shares real,cost real,decision_id integer,status text,closed text,exit_price real,pnl real,review_code text);create table ledger(id integer primary key,created text,kind text,amount real,ref text,balance real);insert into ledger values(1,'2026-01-01','INITIAL',100000,'x',100000);create table company_fundamentals(ticker text primary key,cik text,revenue real,operating_income real,cash real,debt real,shares real,market_cap real,backlog real,as_of text,source_url text);insert into company_fundamentals values('TEST','1',1000000000,100000000,1,1,10000000,2000000000,400000000,'2026-01-01','SEC');create table quote_cache(ticker text primary key,price real,source text,quoted_at text,updated_epoch real);create table position_event_links(position_id integer,news_uid text,linked_at text,relevance real,direction real,scope text,reason text,primary key(position_id,news_uid));insert into news values(1,'n','SEC','TEST wins $500 million contract','funded award','u','2026-01-01','2026-01-01',1);insert into decisions values(1,'2026-01-01','n','TEST','BUY',85,'reason','3.6','EXECUTED',100,100,10000,'Defense');insert into theses values(1,'government_contract','{"source_quality":15,"entity_evidence":20,"novelty":15}','3.0');insert into positions values(1,'TEST','Defense','2026-01-05T15:00:00+00:00',100,100,10000,1,'OPEN',null,null,null,null);""");d.commit();plans.refresh(d);ex.init(d);return t,d
 def asof(self):return dt.datetime(2026,1,6,15,0,tzinfo=dt.timezone.utc)
 def qp(self,price,age=0):
  return lambda d,p,a:{'price':price,'source':'TEST','quoted_at':(a-dt.timedelta(seconds=age)).isoformat(),'age':age}
 def plan(self,d,**kw):
  sets=','.join(k+'=?' for k in kw);d.execute('update position_forecast_plans set '+sets+' where active=1',tuple(kw.values()));d.commit()
 def test_stale_quote_blocks_all_mutation(self):
  t,d=self.db();r=ex.run(d,self.qp(200,181),self.asof());self.assertEqual(r['blocked_stale'],1);self.assertEqual(d.execute("select status from positions").fetchone()[0],'OPEN');self.assertEqual(d.execute('select count(*) from virtual_exit_actions').fetchone()[0],0);t.cleanup()
 def test_stop_closes_and_updates_cash(self):
  t,d=self.db();self.plan(d,stop_price=98,stop_return=-.02,target_price=110,target_return=.10,partial_exit_pct=.7);r=ex.run(d,self.qp(97),self.asof());self.assertEqual(r['actions_committed'],1);self.assertEqual(d.execute('select status from positions').fetchone()[0],'CLOSED');self.assertEqual(d.execute('select phase from position_lifecycle').fetchone()[0],'CLOSED');self.assertGreater(d.execute('select balance from ledger order by id desc').fetchone()[0],100000);t.cleanup()
 def test_rapid_target_hit_reforecasts_and_holds(self):
  t,d=self.db();self.plan(d,target_return=.03,target_price=103,bull_return=.12,confidence=80,max_hold_days=5,runner_target_return=.08);r=ex.run(d,self.qp(104),self.asof());self.assertEqual(r['holds_extended'],1);self.assertEqual(d.execute('select count(*) from virtual_exit_actions').fetchone()[0],0);self.assertEqual(d.execute('select decision from target_reforecasts').fetchone()[0],'HOLD_EXTENDED');self.assertGreater(d.execute('select target_price from position_forecast_plans where active=1').fetchone()[0],104);t.cleanup()
 def test_rapid_target_weak_forecast_follows_partial_exit(self):
  t,d=self.db();self.plan(d,target_return=.03,target_price=103,bull_return=.04,confidence=40,max_hold_days=5,partial_exit_pct=.7,runner_target_return=.08,runner_stop_return=.005);r=ex.run(d,self.qp(104),self.asof());self.assertEqual(r['actions_committed'],1);self.assertEqual(d.execute('select phase from position_lifecycle').fetchone()[0],'RUNNER_OPEN');self.assertAlmostEqual(d.execute('select remaining_shares from position_lifecycle').fetchone()[0],30);self.assertEqual(d.execute('select decision from target_reforecasts').fetchone()[0],'EXIT_PLAN');self.assertAlmostEqual(d.execute('select target_return from position_forecast_plans where active=1').fetchone()[0],.08);t.cleanup()
 def test_runner_target_closes_remaining(self):
  t,d=self.db();self.plan(d,target_return=.03,target_price=103,bull_return=.04,confidence=40,max_hold_days=5,partial_exit_pct=.7,runner_target_return=.08,runner_stop_return=.005);ex.run(d,self.qp(104),self.asof());r=ex.run(d,self.qp(109),self.asof()+dt.timedelta(minutes=10));self.assertEqual(r['actions_committed'],1);self.assertEqual(d.execute('select status from positions').fetchone()[0],'CLOSED');self.assertEqual(d.execute('select count(*) from virtual_exit_actions where status="COMMITTED"').fetchone()[0],2);t.cleanup()
 def test_time_expiry(self):
  t,d=self.db();self.plan(d,target_price=120,stop_price=80,max_hold_days=1,partial_exit_pct=1.0);r=ex.run(d,self.qp(101),self.asof()+dt.timedelta(days=2));self.assertEqual(d.execute('select trigger from virtual_exit_actions').fetchone()[0],'TIME_EXPIRED');t.cleanup()
 def test_thesis_invalidation_precedes_target(self):
  t,d=self.db();p=d.execute('select id,created from position_forecast_plans where active=1').fetchone();d.execute("insert into position_event_links values(1,'bad','2099-01-01',1,-1,'company','contract cancelled')");d.commit();self.plan(d,target_price=101,stop_price=90);ex.run(d,self.qp(110),self.asof());self.assertEqual(d.execute('select trigger from virtual_exit_actions').fetchone()[0],'THESIS_INVALIDATED');t.cleanup()
 def test_ambiguous_range_stop_first(self):
  t,d=self.db();p=d.execute('select id from position_forecast_plans where active=1').fetchone()[0];self.plan(d,target_price=105,stop_price=95);d.execute('insert into v363_price_ranges values(1,?,"2026-01-06",94,106,"BAR",0,null)',(p,));d.commit();ex.run(d,self.qp(100),self.asof());self.assertEqual(d.execute('select trigger from virtual_exit_actions').fetchone()[0],'STOP_REACHED');t.cleanup()
 def test_idempotent_no_double_ledger(self):
  t,d=self.db();self.plan(d,stop_price=98,target_price=110);ex.run(d,self.qp(97),self.asof());n=d.execute('select count(*) from ledger').fetchone()[0];ex.run(d,self.qp(97),self.asof());self.assertEqual(d.execute('select count(*) from ledger').fetchone()[0],n);t.cleanup()
 def test_action_contains_plan_and_evidence(self):
  t,d=self.db();self.plan(d,stop_price=98,target_price=110);ex.run(d,self.qp(97),self.asof());r=d.execute('select * from virtual_exit_actions').fetchone();self.assertIn('target_price',r['plan_json']);self.assertIn('held_sessions',r['evidence_json']);self.assertEqual(r['status'],'COMMITTED');t.cleanup()
if __name__=='__main__':unittest.main()
